<?php
/**
 * Model-aware firmware package manager.
 *
 * A selectable bundle is derived from the files physically present on the
 * selected site's TFTP volume.  Archives are deliberately not treated as
 * firmware: FreePBX does not safely unpack arbitrary vendor packages.
 */
if (!defined('FREEPBX_IS_AUTH')) { die('No direct script access allowed'); }
$sites = $ucm->getSites();
$models = array_values(array_filter($ucm->getModels(), static function (array $model): bool {
    return \FreePBX\modules\Ucmprovisioner\ModelCatalog::unsupportedReason(
        (string)$model['vendor'],
        (string)$model['model']
    ) === null;
}));
$firmwareProfiles = [];
foreach ($models as $model) {
    $vendor = (string)$model['vendor'];
    $profile = \FreePBX\modules\Ucmprovisioner\ModelCatalog::firmwareProfile($vendor, (string)$model['model']);
    if ($profile === null || $profile === '') {
        continue;
    }
    if (!isset($firmwareProfiles[$profile])) {
        $firmwareProfiles[$profile] = [
            'profile' => $profile,
            'vendor' => $vendor,
            'family' => (string)$model['family'],
            'models' => [],
        ];
    }
    $firmwareProfiles[$profile]['models'][] = (string)$model['model'];
}
ksort($firmwareProfiles, SORT_NATURAL | SORT_FLAG_CASE);
$firmwareScopes = [];
foreach ($models as $model) {
    $vendor = (string)$model['vendor'];
    $modelName = (string)$model['model'];
    $profile = \FreePBX\modules\Ucmprovisioner\ModelCatalog::firmwareProfile($vendor, $modelName);
    if ($profile === null || $profile === '') { continue; }
    $scopeKey = strcasecmp($vendor, 'Cisco') === 0
        ? $profile
        : \FreePBX\modules\Ucmprovisioner\ModelCatalog::seriesKey($vendor, $modelName, (string)$model['family']);
    $key = strtolower($vendor) . '|' . $scopeKey;
    if (!isset($firmwareScopes[$key])) {
        $firmwareScopes[$key] = [
            'vendor'=>$vendor,
            'key'=>$scopeKey,
            'label'=>strcasecmp($vendor, 'Cisco') === 0
                ? (string)($firmwareProfiles[$profile]['label'] ?? implode(' / ', $firmwareProfiles[$profile]['models'] ?? []))
                : strtoupper(str_replace('_', ' ', $scopeKey)),
            'profile'=>strcasecmp($vendor, 'Cisco') === 0 ? $profile : '',
            'models'=>[],
        ];
    }
    $firmwareScopes[$key]['models'][] = ['model'=>$modelName, 'profile'=>$profile];
}
$firmwareScopes = array_values($firmwareScopes);
usort($firmwareScopes, static fn(array $left, array $right): int =>
    strnatcasecmp($left['vendor'].'|'.$left['label'], $right['vendor'].'|'.$right['label'])
);
$ciscoLocaleProfiles = \FreePBX\modules\Ucmprovisioner\ModelCatalog::CISCO_LOCALE_PROFILES;
$ciscoLocaleFirmwareMap = [];
foreach ($ciscoLocaleProfiles as $profileId=>$profile) {
    $ciscoLocaleFirmwareMap[(string)$profile['firmware_profile']] = (string)$profileId;
}
$defaultSite = (int)($_REQUEST['site_id'] ?? 0);
if ($defaultSite < 1 || !array_filter($sites, static fn(array $site): bool => (int)($site['id'] ?? 0) === $defaultSite)) {
    $defaultSite = $ucm->localSiteId();
}
$h = static fn($value) => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
?>
