  function showFirmwarePanel(name){$('.ucm-firmware-panel').prop('hidden',true).filter('[data-firmware-panel="'+name+'"]').prop('hidden',false);$('[data-firmware-tab]').removeClass('is-active').attr('aria-selected','false').filter('[data-firmware-tab="'+name+'"]').addClass('is-active').attr('aria-selected','true');}
  $('[data-firmware-tab]').on('click',function(){showFirmwarePanel(String($(this).data('firmware-tab')||'packages'));});
  function refreshScope(){var brand=vendor(),old=String($('#ucm-fw-series').val()||''),series=$('#ucm-fw-series').empty().append($('<option value="">').text(brand?'Choose firmware family / series':'Choose a brand first')),rows=scopes.filter(function(row){return row.vendor===brand;});rows.forEach(function(row){series.append($('<option>').val(row.key).text(row.label));});series.prop('disabled',!brand);if(old&&rows.some(function(row){return row.key===old;}))series.val(old);var row=scope(),model=$('#ucm-fw-model').empty().append($('<option value="">').text(row&&row.models.length?'All compatible models in this scope':'No narrower model scope'));(row&&row.models||[]).forEach(function(item){model.append($('<option>').val(item.model).text(item.model));});model.prop('disabled',!row||!row.models.length);if(row&&localeProfileByFirmware[row.profile])$('#ucm-locale-profile').val(localeProfileByFirmware[row.profile]);refreshInventory();}
